import{_ as i,o as n,c as o,a0 as a}from"./chunks/framework.CNDWyMYS.js";const h=JSON.parse('{"title":"Pinning versions with a lock file","description":"","frontmatter":{},"headers":[],"relativePath":"pinning_versions_with_a_lock_file.md","filePath":"pinning_versions_with_a_lock_file.md"}'),c={name:"pinning_versions_with_a_lock_file.md"};function s(t,e,d,l,r,p){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="pinning-versions-with-a-lock-file" tabindex="-1">Pinning versions with a lock file <a class="header-anchor" href="#pinning-versions-with-a-lock-file" aria-label="Permalink to &quot;Pinning versions with a lock file&quot;">​</a></h1><p>Pinning dependency versions is a way to get more predictable builds. As explained in <a href="https://before-you-ship.18f.gov/infrastructure/pinning-dependencies/" target="_blank" rel="noreferrer">this page</a>:</p><blockquote><p>The practice of “pinning dependencies” refers to making explicit the versions of software your application depends on (defining the dependencies of new software libraries is outside the scope of this document). Dependency pinning takes different forms in different frameworks, but the high-level idea is to “freeze” dependencies so that deployments are repeatable. Without this, we run the risk of executing different software whenever servers are restaged, a new team-member joins the project, or between development and production environments.</p></blockquote><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Node.js Developer Quick Tip</strong>:</p><ul><li>The <code>luarocks.lock</code> file is the direct equivalent of <strong><code>package-lock.json</code></strong> or <strong><code>yarn.lock</code></strong>.</li><li>Unlike npm, which generates a lockfile automatically on <code>npm install</code>, you generate <code>luarocks.lock</code> by passing the <code>--pin</code> option when running <code>luarocks build</code> or <code>luarocks make</code>.</li><li>Once the <code>luarocks.lock</code> file is generated, subsequent calls to <code>luarocks build</code> or <code>luarocks make</code> will read this lockfile to install the exact locked versions, similar to running <code>npm install</code> with an existing <code>package-lock.json</code>.</li></ul></div><h2 id="pinning-dependencies-in-luarocks" tabindex="-1">Pinning dependencies in LuaRocks <a class="header-anchor" href="#pinning-dependencies-in-luarocks" aria-label="Permalink to &quot;Pinning dependencies in LuaRocks&quot;">​</a></h2><p>To pin dependencies in LuaRocks, you build a package as usual, using <code>luarocks build</code> or <code>luarocks make</code>, and add the <code>--pin</code> option. This will build the package and its dependencies, and will also create a <code>luarocks.lock</code> file in the current directory. This is a text file containing the names and versions of all dependencies (and its dependencies, recursively) that were installed, with the exact versions used when building.</p><h2 id="using-pinned-dependencies-in-luarocks" tabindex="-1">Using pinned dependencies in LuaRocks <a class="header-anchor" href="#using-pinned-dependencies-in-luarocks" aria-label="Permalink to &quot;Using pinned dependencies in LuaRocks&quot;">​</a></h2><p>When building a package with <code>luarocks build</code>, <code>luarocks make</code> (or via <code>luarocks install</code> if there is not prebuilt binary package), <em>without</em> using <code>--pin</code>, if the current directory contains a <code>luarocks.lock</code> file, it is used as the authoritative source for exact version of all dependencies, both immediate and recursively loaded dependencies. For each dependency that is recursively scanned, LuaRocks will attempt to use the version in the <code>luarocks.lock</code> file, ignoring the version constraints in the rockspec.</p><p>When building a package using a lock file, <code>luarocks.lock</code> is copied to the package&#39;s metadata directory (e.g. <code>/usr/local/luarocks/rocks/5.3/name/version/luarocks.lock</code>) — if you later pack it as a binary rock with <code>luarocks pack</code>, the lock file will be packaged inside the rock, and will be used when that binary rock is installed with <code>luarocks install</code>.</p><h2 id="updating-pinned-dependencies" tabindex="-1">Updating pinned dependencies <a class="header-anchor" href="#updating-pinned-dependencies" aria-label="Permalink to &quot;Updating pinned dependencies&quot;">​</a></h2><p>Building a package again with the <code>--pin</code> flag ignores any existing <code>luarocks.lock</code> file and recreates this file, by scanning dependency based on the dependency constraints specified in the rockspec.</p><p>It is also possible to edit the <code>luarocks.lock</code> by hand, of course, but there are no checks: if the versions you set for the various dependencies are not compatible with each other, LuaRocks won&#39;t be able to do anything about it and will blindly follow what is set on the <code>luarocks.lock</code> file.</p>',12)])])}const k=i(c,[["render",s]]);export{h as __pageData,k as default};
